/* Synthwave City - a small bold sans-serif text face drawn from strokes, for the hologram ads. PURE C99.
 *
 * The web version draws its ad text with whatever "system-ui" font the machine has. This port has no font
 * file (every picture is generated by code), so the letters here are skeletons - a few lines and arcs each -
 * that are stroked wide enough to read as a heavy sans. Metrics follow a typical heavy grotesque: capitals
 * 0.72 em tall, advances per letter, a stem of 0.14 to 0.19 em depending on the weight. Characters: A-Z, 0-9,
 * the space and  . : - / %  (lower case draws as upper case; anything else is a blank of one advance). */
#ifndef SWC_FONT_H
#define SWC_FONT_H

#include <stdbool.h>

#include "swc_raster.h"

typedef struct SwcFontStyle {
    double size;    /* em in pixels */
    int weight;     /* 700 (bold) .. 900 (black) */
    bool italic;    /* leans the letters 0.2 to the right */
    bool mono;      /* a monospaced face: every advance is 0.6 em, a little lighter */
    double spacing; /* extra pixels after every letter */
} SwcFontStyle;

#define SWC_FONT_CAP_HEIGHT 0.72 /* of the em */

/* Width of one letter's advance, without the spacing. */
double swc_font_advance(const SwcFontStyle *st, char c);
/* Width of a line, spacing included after every letter (the last too), as a browser measures it. */
double swc_font_measure(const SwcFontStyle *st, const char *text);
/* The stroke width that makes the letters, in pixels. */
double swc_font_stem(const SwcFontStyle *st);

/* Draws `text` with its left edge at x and its baseline at y, painting with the canvas's fill style. With
 * `widen` > 0 the letters are made that much wider on every side in total (a halo to draw under the letters,
 * like the outline stroke of a canvas's strokeText); with `ring` as well, only that outline is painted and
 * the insides stay as they were. The canvas state is restored. */
void swc_font_draw(SwcCanvas *cv, const SwcFontStyle *st, const char *text, double x, double y, double widen,
                   bool ring);

#endif
